<template><div class="demo-widget universal-demo-widget" :style="style"><span class="widget-kicker">{{ kicker }}</span><b>{{ title }}</b><p>{{ subtitle }}</p><div v-if="widget.settings.progress!==undefined" class="progress-track"><i :style="{width:`${widget.settings.progress}%`}"></i></div></div></template>
<script setup>import{computed}from'vue';import{useWidgetEvents}from'../../widgetHelpers.js';const props=defineProps({widget:{type:Object,required:true},runtimeMode:{type:String,default:'editor-preview'}});const alertTypes=new Set(['subscription-alert','raid-alert']);const event=useWidgetEvents(props.widget,props.runtimeMode==='browser-source'&&alertTypes.has(props.widget.type)?null:{actor:null,payload:{}});const style=computed(()=>({background:props.widget.settings.background,opacity:props.widget.settings.opacity,borderRadius:`${props.widget.settings.cornerRadius}px`,color:props.widget.settings.color||'#fff'}));const kicker=computed(()=>props.runtimeMode==='browser-source'&&alertTypes.has(props.widget.type)?(props.widget.type==='raid-alert'?'Incoming raid':'New subscriber'):props.widget.settings.kicker);const title=computed(()=>{if(!event.value||props.runtimeMode!=='browser-source')return props.widget.settings.title;const actor=event.value.actor?.displayName||'A community member';return props.widget.type==='raid-alert'?`${actor} brought ${event.value.payload?.viewers||0} viewers`:`${actor} subscribed!`});const subtitle=computed(()=>props.runtimeMode==='browser-source'&&alertTypes.has(props.widget.type)?'':props.widget.settings.subtitle)</script>
